always @(posedge Clock1 or posedge Clock2 or posedge Clock3) begin
    if (Reset) begin
        currentClock <= 2'b00;
        nextClock <= 2'b00;
        ClockOut <= 1'b0;
    end else begin
        currentClock <= nextClock;
        if (Clock1) nextClock[0] <= 1'b1;
        if (Clock2) nextClock[1] <= 1'b1;
        if (Clock3) nextClock <= 2'b11;
        if (nextClock == 2'b00) ClockOut <= Clock1;
        else if (nextClock == 2'b01) ClockOut <= Clock2;
        else if (nextClock == 2'b10 || nextClock == 2'b11) ClockOut <= Clock3;
    end
end

endmodule

module top_module(
    input A,
    input B,
    input SEL,
    output reg OUT
);wire TG_A, TG_B;

assign TG_A = (SEL == 1'b0) ? A : 1'bZ;
assign TG_B = (SEL == 1'b1) ? B : 1'bZ;

assign OUT = TG_A & TG_B;

endmodule

