        4'h0: segout = ~7'b0111111;
        4'h1: segout = ~7'b0000110;
        4'h2: segout = ~7'b1011011;
        4'h3: segout = ~7'b1001111;
        4'h4: segout = ~7'b1100110;
        4'h5: segout = ~7'b1101101;
