        4'h9: segout = ~7'b1100111;
        4'hA: segout = ~7'b1110111;
        4'hB: segout = ~7'b1111100;
        4'hC: segout = ~7'b0111001;
        4'hD: segout = ~7'b1011110;
        4'hE: segout = ~7'b1111001;
        4'hF: segout = ~7'b1110001;

