module top_module(g, p, c_in, g_out, p_out, c_out);input [1:0] g, p;
  input c_in;
  output [1:0] g_out, p_out;
  output c_out;
  assign g_out = {{1'b0}, g[1]} | {{1'b0}, {1'b0}} & {g[0], p[1]};
  assign p_out = {p[1], p[0]} & {1'b1, 1'b1};
  assign c_out = {g[0], p[0]} & {c_in, 1'b1} | {{1'b0}, g[1]} & {{1'b0}, {1'b0}} & {c_in, p[1]};
endmodule

module sprinkler_system (
	input clk,
	input resetn,
	input start,
	output reg sprinkling);

	parameter OFF=0, SPRINKLING=1;
	reg state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= OFF;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			OFF: next_state = start ? SPRINKLING : OFF;
			SPRINKLING: next_state = OFF;
			default: next_state = OFF;
		endcase
	end

	always @(state) begin
		case (state)
			SPRINKLING: sprinkling = 1;
			default: sprinkling = 0;
		endcase
	end
endmodule

module shift_register (
    input clk,
    input serial_in,
    output reg [3:0] parallel_out
);

    // Shift register logic
    always @(posedge clk) begin
        parallel_out <= {serial_in, parallel_out[3:1]};
    end

endmodule

