    i_data0,
    o_data0
);

code:
module top_module(
    i_data0,
    o_data0
);// Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0]
    o_data0;

  //Multipliers:

  wire [31:0]
    w1,
    w512,
    w511,
    w4,
    w507,
    w4056,
    w4057,
    w32456;

  assign w1 = i_data0;
  assign w512 = w1 << 9;
  assign w511 = w512 - w1;
  assign w4 = w1 << 2;
  assign w507 = w511 - w4;
  assign w4056 = w507 << 3;
  assign w4057 = w1 + w4056;
  assign w32456 = w4057 << 3;

  assign o_data0 = w32456;

  //multiplier_block area estimate = 4833.25917057353;
endmodule

