description:
Design a fixed-priority arbiter for N input requests that generates corresponding grants. The arbiter allows only one request to be granted at a time based on fixed priority, where lower-indexed requests have higher priority. The module uses a waitmask to ensure that a higher-priority request can grant access when lower-priority requests are also active, effectively preventing simultaneous grants.
module top_module(

   grants,

   requests
   );

code:
module top_module(

   grants,

   requests
   );parameter N    = 99;
   parameter TYPE = "FIXED"; 





   input  [N-1:0] requests;  
   output [N-1:0] grants;    

   wire [N-1:0]   waitmask; 
   genvar 	  j;     
   generate       
      if(TYPE=="FIXED")
	begin : arbiter_fixed
	   assign waitmask[0]   = 1'b0;      
	   for (j=N-1; j>=1; j=j-1) 
	     begin : gen_arbiter     
		assign waitmask[j] = |requests[j-1:0];
	     end
	end
   endgenerate


   assign grants[N-1:0] = requests[N-1:0] & ~waitmask[N-1:0];

endmodule

