module top_module(
  output O,
  input  D, WCLK, WE,
  input  A0, A1, A2, A3, A4, A5
);parameter [63:0] INIT = 64'bx;
    parameter IS_WCLK_INVERTED = 0;

    // Instantiate a memory block (define a simpler RAM implementation if DPRAM64 is unknown)
    reg [63:0] mem; // 64-bit memory
    wire [5:0] addr = {A5, A4, A3, A2, A1, A0}; // 6-bit address

    // Write operation
    always @(posedge WCLK or negedge WE) begin
        if (WE) begin
            mem[addr] <= D; // Write data to memory
        end
    end

    // Read operation
    assign O = mem[addr]; // Output the data from memory

endmodule

