module top_module(


    input CLK, 
    input RESET, 


    input PB, 

    output DEBOUNCED, 
	output PB_DOWN,	
	output PB_UP	

    );reg debounced;
	wire sync_0;
	wire sync_1;
	reg [16:0] counter; 

	wire counter_max = &counter; 
	wire idle = ( debounced==sync_1 );





	assign DEBOUNCED = debounced;
	assign PB_DOWN = ~idle & counter_max & ~debounced;
	assign PB_UP = ~idle & counter_max & debounced;
    assign sync_0 = ~PB;
	assign sync_1 = sync_0; 

    always @( posedge CLK ) begin
        if ( !RESET ) begin


			debounced <= 0;
			counter <= 0;

        end
        else begin
			if ( idle ) begin
				counter <= 0; 
			end
			else begin
				counter <= counter + 1;
				if ( counter_max ) begin
					debounced <= ~debounced;
				end
			end

		end
    end

endmodule

