module elevator_system (
	input clk,
	input resetn,
	input [1:0] request,
	output up,
	output down);

	parameter IDLE=0, MOVING_UP=1, MOVING_DOWN=2;
	reg [1:0] state, next_state;
	reg [1:0] current_floor;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (~resetn) current_floor <= 2'b00; // Start at ground floor
		else if (state == MOVING_UP) current_floor <= current_floor + 2'b01;
		else if (state == MOVING_DOWN) current_floor <= current_floor - 2'b01;
		else current_floor <= current_floor;
	end

	always_comb begin
		case (state)
			IDLE: begin
				if (request > current_floor) next_state = MOVING_UP;
				else if (request < current_floor) next_state = MOVING_DOWN;
				else next_state = IDLE;
			end
			MOVING_UP: next_state = (current_floor == request) ? IDLE : MOVING_UP;
			MOVING_DOWN: next_state = (current_floor == request) ? IDLE : MOVING_DOWN;
			default: next_state = IDLE;
		endcase
	end

	assign up = (state == MOVING_UP);
	assign down = (state == MOVING_DOWN);
endmodule

