  reg cmd_stop; 
  always @(posedge clk or negedge nReset) 
  if (~nReset) 
  cmd_stop <= #1 1'b0; 
  else if (rst) 
  cmd_stop <= #1 1'b0; 
  always @(posedge clk or negedge nReset) 
  if (~nReset) 
