  assign O = Q[15];
  assign r_rlast = s_axburst_eq0 & Q[15] & s_axburst_eq1;
  assign m_axi_arready = sel_first & si_rs_arvalid;

  wire s_axburst_eq0 = Q[2] & ~Q[1] & ~Q[0];
  wire s_axburst_eq1 = Q[2] & ~Q[1] & Q[0];

endmodule

