module top_module(
        clk         ,   // clock
        ce          ,   // clock enable
        nrst        ,   // asyn reset
        reset       ,   // sync reset
        din         ,   // data input
        dout        ,   // data output
        rd          ,   // read
        wr          ,   // write
        full        ,   // fifo full
        empty       ,   // fifo empty
        nsin        ,   // num of shift in (bits), could be 4, 6 or 8
        nsout           // num of shift out (bits), could be 2 or 4.
        ) ;input           clk ;
input           ce ;
input           nrst ;
input           reset ;
input   [7:0]   din ;
output  [7:0]   dout ;
input           rd ;
input           wr ;
output          full ;
output          empty ;
input   [3:0]   nsin ;
input   [1:0]   nsout ;

//=========================
// Internal signal
//=========================
reg     [127:0] buffer ;
reg     [3:0]   cnt ;
wire    [31:0]  shift_out ;
wire    [63:0]  shift_in ;
wire    [3:0]   space_left ;

//=========================
// Main RTL
//=========================
assign full = (cnt + nsin) > 16 ;
assign empty = cnt < nsout ;

always @ (posedge clk or negedge nrst)
  if (~nrst)
    cnt <= 0 ;
  else if (ce)
  begin
    if (reset)
      cnt <= 0 ;
    else
    begin
      if (wr & rd)
        cnt <= cnt + nsin - nsout ;
      if (wr & ~rd)
        cnt <= cnt + nsin ;
      if (~wr & rd)
        cnt <= cnt - nsout ;
    end
  end

assign shift_out = {2'h0, buffer} << nsout ;  
assign dout = shift_out [31:24] ; 

assign space_left = rd ? 16 - cnt + nsout : 16 - cnt ;  
assign shift_in = {64'h0, din} << space_left ;

always @ (posedge clk or negedge nrst)
  if (~nrst)
    buffer <= 0 ;
  else if (ce)
  begin
    if (reset)
      buffer <= 0 ;
    else
    begin
      if (wr & rd)
        buffer <= shift_out [127:0] | shift_in [63:0] ;
      if (wr & ~rd)
        buffer <= buffer | shift_in [63:0] ;
      if (~wr & rd)
        buffer <= shift_out [127:0] ;
    end
  end  

endmodule

module binary_counter(
    input clk,
    input rst,
    output reg [3:0] q
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        q <= 4'd0;
    end else begin
        q <= q + 1;
    end
end

endmodule

