description:
Design a random number generator that outputs a 64-bit data word. When the reset signal is high, the output initializes to a value composed of the hexadecimal number 'F' repeated 16 times; otherwise, it initializes to 'A' repeated 16 times. The module computes a feedback bit based on specific bits of the initialized data word for generating pseudo-random sequences. On the falling edge of the reset signal, the output is updated to shift the data left by one bit, inserting the feedback bit into the least significant position.
module top_module(
  input reset,
  output reg [63:0] outData
);

code:
module top_module(
  input reset,
  output reg [63:0] outData
);wire feedback;
  wire [63:0]data1;
  assign data1 = (reset) ? {16{4'hf}} : {16{4'ha}};
  assign feedback = data1[63] ^ data1[9] ^ data1[7] ^ data1[5] ^ data1[3] ^ data1[0];

  always @(negedge reset) begin
	 outData <= {data1[62:0], feedback};
  end

endmodule

module full_adder
(
  input a, 
  input b, 
  input carry_in, 

  output sum, 
  output carry_out
);

  assign {carry_out, sum} = a + b + carry_in;

endmodule

module ripple_carry_adder
(
  input [3:0] a,
  input [3:0] b,
  input carry_in,

  output [3:0] sum,
  output carry_out
);

  wire c1, c2, c3;

  full_adder fa0 (.a(a[0]), .b(b[0]), .carry_in(carry_in), .sum(sum[0]), .carry_out(c1));
  full_adder fa1 (.a(a[1]), .b(b[1]), .carry_in(c1), .sum(sum[1]), .carry_out(c2));
  full_adder fa2 (.a(a[2]), .b(b[2]), .carry_in(c2), .sum(sum[2]), .carry_out(c3));
  full_adder fa3 (.a(a[3]), .b(b[3]), .carry_in(c3), .sum(sum[3]), .carry_out(carry_out));

endmodule

